package com.phoneTech.demo.devices.service;
import com.phoneTech.demo.devices.dto.*; import com.phoneTech.demo.devices.entity.*; import com.phoneTech.demo.devices.enums.UnlockToolSupportStatus; import com.phoneTech.demo.devices.exception.DeviceNotFoundException; import com.phoneTech.demo.devices.exception.DeviceVariantNotFoundException; import com.phoneTech.demo.devices.repository.*; import com.phoneTech.demo.projects.exception.InvalidImageException; import com.phoneTech.demo.projects.storage.StorageService; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.multipart.MultipartFile; import java.util.*;
@Service public class DeviceService {
 private static final int DEFAULT_SIZE=20,MAX_SIZE=100; private final PhoneModelRepository models; private final PhoneVariantRepository variants; private final PhoneVariantPriceRepository prices; private final DiagnosticFaultRepository faults; private final StorageService storage; private final PhoneModelVariantRepository legacyVariants;
 @Autowired public DeviceService(PhoneModelRepository m,PhoneVariantRepository v,PhoneVariantPriceRepository p,DiagnosticFaultRepository f,StorageService s){models=m;variants=v;prices=p;faults=f;storage=s;legacyVariants=null;}
 public DeviceService(PhoneModelRepository m,PhoneModelVariantRepository v,StorageService s){models=m;legacyVariants=v;variants=null;prices=null;faults=null;storage=s;}
 @Transactional(readOnly=true) public DevicePageResponse getDevices(String q,int page,int size){int pg=Math.max(0,page),sz=size<=0?DEFAULT_SIZE:Math.min(size,MAX_SIZE);String query=q==null?"":q.trim();long total=models.countDeviceSummaries(query);List<DeviceSummaryResponse> items=models.findDeviceSummaries(query,sz,(int)Math.min(Integer.MAX_VALUE,(long)pg*sz)).stream().map(r->new DeviceSummaryResponse(r.getId(),r.getBrand(),r.getCommercialName(),r.getImageUri(),status(r.getUnlockToolStatus()))).toList();int pages=(int)Math.ceil((double)total/sz);return new DevicePageResponse(items,pg,sz,total,pages,pg+1<pages);}
 @Transactional(readOnly=true) public DeviceDetailResponse getDevice(Long id){return detail(find(id));}
 @Transactional(readOnly=true) public List<DeviceVariantResponse> getDeviceVariants(Long id){find(id);if(legacyVariants!=null)return legacyVariants.findByPhoneModelIdAndIsActiveTrueOrderByIsCommonDescCodeAsc(id).stream().map(v->new DeviceVariantResponse(v.getId(),v.getCode(),v.getRam(),v.getStorage(),v.getResalePrice(),v.isCommon())).toList();return variants.findByPhoneModelIdAndActiveTrueOrderByModelCodeAsc(id).stream().map(v->{ResaleEstimateResponse e=firstPrice(v.getId());return new DeviceVariantResponse(v.getId(),v.getModelCode(),v.getRamGb()==null?null:v.getRamGb()+" GB",v.getStorageGb()==null?null:v.getStorageGb()+" GB",e==null?null:e.amount(),false,v.getImageUri());}).toList();}
 @Transactional(readOnly=true) public DeviceSelectionDataResponse getSelectionData(Long id){PhoneModel m=find(id);return new DeviceSelectionDataResponse(detail(m),unlock(m),variants.findByPhoneModelIdAndActiveTrueOrderByModelCodeAsc(id).stream().map(this::variant).toList(),getDiagnosisCategories());}
 @Transactional(readOnly=true) public UnlockToolSupportResponse getUnlockToolSupport(Long id){return unlock(find(id));}
 @Transactional(readOnly=true) public List<DiagnosisCategoryResponse> getDiagnosisCategories(){Map<String,List<DiagnosticFault>> g=new LinkedHashMap<>();faults.findByActiveTrueOrderByComponentCodeAscSortOrderAscFaultCodeAsc().forEach(f->g.computeIfAbsent(f.getComponentCode(),x->new ArrayList<>()).add(f));return g.values().stream().sorted(Comparator.comparingInt(x->x.getFirst().getSortOrder())).map(x->{DiagnosticFault f=x.getFirst();return new DiagnosisCategoryResponse(null,f.getComponentCode(),f.getComponentName(),null,null,f.getSortOrder(),true,x.stream().map(a->new DiagnosisFaultResponse(a.getId(),a.getFaultCode(),a.getFaultName(),a.getDescription(),a.getImageUri(),a.getSortOrder(),a.isActive())).toList());}).toList();}
 @Transactional public DeviceDetailResponse uploadImage(Long id,MultipartFile file){PhoneModel m=find(id);if(file==null||file.isEmpty())throw new InvalidImageException("The image file is empty");String type=file.getContentType();String ext=Map.of("image/jpeg","jpg","image/png","png","image/webp","webp","image/gif","gif").get(type==null?"":type.toLowerCase());if(ext==null)throw new InvalidImageException("Unsupported image type: "+type);String previousImageUri=m.getImageUri();String name=storage.store(file,ext);try{m.updateImageUri("/uploads/"+name);models.save(m);}catch(RuntimeException e){storage.delete(name);throw e;}if(previousImageUri!=null&&previousImageUri.startsWith("/uploads/")){storage.delete(previousImageUri.substring("/uploads/".length()));}return detail(m);}
 @Transactional public SelectionVariantResponse uploadVariantImage(Long deviceId,Long variantId,MultipartFile file){find(deviceId);PhoneVariant variant=findVariant(deviceId,variantId);String ext=imageExtension(file);String previousImageUri=variant.getImageUri();String name=storage.store(file,ext,"variants");try{variant.updateImageUri("/uploads/variants/"+name);variants.save(variant);}catch(RuntimeException e){storage.delete("variants",name);throw e;}if(previousImageUri!=null&&previousImageUri.startsWith("/uploads/variants/")){storage.delete("variants",previousImageUri.substring("/uploads/variants/".length()));}return variant(variant);}
 private PhoneModel find(Long id){return models.findById(id).filter(PhoneModel::isActive).orElseThrow(()->new DeviceNotFoundException(id));} private DeviceDetailResponse detail(PhoneModel m){return new DeviceDetailResponse(m.getId(),m.getBrand(),m.getCommercialName(),m.getImageUri(),m.getUnlocktoolStatus());}
 private PhoneVariant findVariant(Long deviceId,Long variantId){return variants.findById(variantId).filter(v->v.isActive()&&v.getPhoneModelId().equals(deviceId)).orElseThrow(()->new DeviceVariantNotFoundException(variantId));}
 private String imageExtension(MultipartFile file){if(file==null||file.isEmpty())throw new InvalidImageException("The image file is empty");String type=file.getContentType();String extension=Map.of("image/jpeg","jpg","image/png","png","image/webp","webp").get(type==null?"":type.toLowerCase());if(extension==null)throw new InvalidImageException("Unsupported image type: "+type);return extension;}
 private UnlockToolSupportResponse unlock(PhoneModel m){UnlockToolSupportStatus s=m.getUnlocktoolStatus()==null?UnlockToolSupportStatus.UNKNOWN:m.getUnlocktoolStatus();String n=s==UnlockToolSupportStatus.SUPPORTED?"Compatible con UnlockTool":s==UnlockToolSupportStatus.UNSUPPORTED?"No compatible con UnlockTool":"Compatibilidad con UnlockTool no verificada";return new UnlockToolSupportResponse(s,n,null,List.of(),null);}
 private SelectionVariantResponse variant(PhoneVariant v){List<ResaleEstimateResponse> es=prices.findByPhoneVariantIdOrderByConditionCodeAsc(v.getId()).stream().map(p->new ResaleEstimateResponse(p.getConditionCode(),p.getReferenceSalePrice(),p.getCurrency(),null,null)).toList();return new SelectionVariantResponse(v.getId(),v.getModelCode(),v.getVariantName(),v.getRamGb()==null?null:v.getRamGb().intValue(),v.getStorageGb()==null?null:v.getStorageGb().intValue(),v.getChipset(),v.getRegion(),v.getUnlockToolStatus(),v.getImageUri(),false,es.stream().findFirst().orElse(null),es);}
 private ResaleEstimateResponse firstPrice(Long id){return prices.findByPhoneVariantIdOrderByConditionCodeAsc(id).stream().findFirst().map(p->new ResaleEstimateResponse(p.getConditionCode(),p.getReferenceSalePrice(),p.getCurrency(),null,null)).orElse(null);} private UnlockToolSupportStatus status(String s){return s==null?UnlockToolSupportStatus.UNKNOWN:UnlockToolSupportStatus.valueOf(s);}
}
